const a=[{cls:"Ótima",range:"80 a 100",meaning:"Excelente condição, adequada à vida aquática e à maioria dos usos da água."},{cls:"Boa",range:"52 a 79",meaning:"Boa condição, com pequenas alterações. Vale acompanhar a evolução."},{cls:"Regular",range:"37 a 51",meaning:"Alterações perceptíveis. A fauna já pode sentir; investigue as causas."},{cls:"Ruim",range:"20 a 36",meaning:"Qualidade comprometida, com provável impacto na biota e nos usos da água."},{cls:"Péssima",range:"0 a 19",meaning:"Condição crítica, com risco para a biota e para a saúde humana."}],e={iqa:{what:"Uma nota de 0 a 100 que resume a qualidade da água a partir de vários parâmetros medidos juntos.",why:"Permite comparar estações e acompanhar mudanças ao longo do tempo sem olhar cada medida separadamente."},do_mgl:{what:"A quantidade de oxigênio disponível na água.",why:"Peixes e invertebrados dependem dele. Abaixo de 5 mg/L a vida aquática sofre, e perto de zero há mortandade (hipóxia)."},coliforms_nmp:{what:"Indicador de contaminação por fezes, humanas e de outros animais, em geral vindas de esgoto.",why:"Acima do limite, a água não é segura para contato direto e indica lançamento de esgoto próximo."},phosphorus_mgl:{what:"Nutriente que alimenta algas e plantas aquáticas.",why:"Em excesso causa eutrofização: floração de algas, queda de oxigênio e mortandade de peixes."},nitrate_mgl:{what:"Forma de nitrogênio que chega com esgoto e fertilizantes.",why:"Junto com o fósforo impulsiona a eutrofização e, em concentração alta, compromete o uso da água."},turbidity_ntu:{what:"O quanto a água está turva por partículas em suspensão.",why:"Reduz a luz que chega a plantas e algas e pode prejudicar as brânquias. Sobe com chuva forte e erosão."},ph:{what:"Indica se a água é ácida ou alcalina, numa escala de 0 a 14.",why:"Fora da faixa de 6 a 9 os organismos ficam estressados. Valores altos no fim da tarde podem indicar floração de algas."},temp_c:{what:"A temperatura da água.",why:"Controla quanto oxigênio a água retém, já que água quente retém menos, e o ritmo do metabolismo dos organismos."},conductivity_uscm:{what:"A capacidade da água de conduzir eletricidade, que reflete os sais dissolvidos.",why:"Aumenta com esgoto, efluentes industriais e entrada de água salgada, e serve de alerta precoce de poluição."}},o={rio:"Rio",lago:"Lago",reservatorio:"Reservatório",estuario:"Estuário"},i=[{term:"Observação por imagem",meaning:"Registro de uma foto da água ou de uma imagem de satélite, lido pela IA e conferido por você. É um indício visual, não uma medição de laboratório."},{term:"Nível de atenção",meaning:"Escala de 0 a 3 para as observações por imagem: sem sinais, atenção baixa, moderada ou alta. Orienta onde olhar primeiro em campo."},{term:"Turbidez aparente",meaning:"O quanto a água parece turva na imagem. Depende da luz e do ângulo, então não substitui a medida em NTU."},{term:"IQA",meaning:"Índice de Qualidade da Água. Nota de 0 a 100, calculada a partir de vários parâmetros, que vai de Péssima a Ótima."},{term:"CONAMA 357/2005",meaning:"Resolução que define os limites legais de cada parâmetro. Aqui se usam os da classe 2, a mais comum para águas doces."},{term:"Dia fora do padrão",meaning:"Dia em que a combinação das medidas fugiu muito do comportamento normal daquela estação, segundo a IA. Pede conferência em campo."},{term:"Evento conhecido",meaning:"Ocorrência já registrada (um vazamento, uma floração) usada para conferir se a IA a enxerga."},{term:"Tendência confirmada",meaning:"Mudança lenta e contínua ao longo dos anos que o teste estatístico considera real, e não variação ao acaso ou da estação do ano."},{term:"Eutrofização",meaning:"Excesso de nutrientes (fósforo e nitrogênio) que provoca floração de algas e falta de oxigênio."},{term:"Hipóxia",meaning:"Falta de oxigênio dissolvido, que sufoca peixes e invertebrados."},{term:"NMP/100 mL",meaning:"Número Mais Provável de coliformes em 100 mililitros de água."},{term:"NTU",meaning:"Unidade de turbidez nefelométrica: quanto maior, mais turva a água."},{term:"Média de 7 dias",meaning:"Média móvel que suaviza a oscilação diária para destacar a direção da mudança."},{term:"Perfil de ecossistema",meaning:"Grupo de meses com água parecida: preservado, intermediário ou impactado."}],r={do_mgl:"mínimo de 5 mg/L",coliforms_nmp:"máximo de 1.000 NMP/100 mL",nitrate_mgl:"máximo de 10 mg/L",turbidity_ntu:"máximo de 100 NTU",phosphorus_mgl:"máximo de 0,1 mg/L em rios, 0,03 mg/L em lagos e reservatórios e 0,124 mg/L em estuários",ph:"entre 6 e 9, ou entre 6,5 e 8,5 em estuários"};export{i as G,a as I,r as L,e as P,o as S};
